'use strict';
const assert = require('node:assert/strict');
const {createHash} = require('node:crypto');
const fs = require('node:fs/promises');
const path = require('node:path');
const os = require('node:os');
const http = require('node:http');
const {chromium} = require(process.env.PLAYWRIGHT_PATH || 'playwright');
const [manifestPath, countArg, output] = process.argv.slice(2);
const rounds = Number(countArg);
assert.ok(manifestPath && output && Number.isInteger(rounds) && rounds >= 1 && rounds <= 64,
  'Usage: node ceiling.cjs MANIFEST.json ROUNDS OUT.json (run from Saba checkout)');
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const count = 1000000;
const positions = Array.from({length:16}, (_,i) => (i+1)*8);
positions.push(...positions.slice(0,-1).reverse(), 0);
const wrapper = `
const name = new URLSearchParams(location.search).get('arm');
const {mountScaleBand: mount} = await import('/arm/' + name + '.js');
window.replacements = [];
export function mountScaleBand(host, records, first) {
  let ready;
  const band = mount(host, records, first, () => { ready = performance.now(); });
  return {
    replace(records, first) {
      ready = undefined;
      const start = performance.now();
      band.replace(records, first);
      const end = performance.now(), ms = end - start;
      const snapshotMs = ready === undefined ? undefined : ready - start;
      const readyReplaceMs = ready === undefined ? undefined : end - ready;
      window.replacements.push({first: records[0].id, end: records.at(-1).id+1, ms, snapshotMs, readyReplaceMs});
    },
    dispose: () => band.dispose()
  };
}`;

// The checks run outside renderer and presentation stopwatches.
function installChecks(identity) {
  const requireTrue = (condition, message) => { if (!condition) throw Error(message); };
  let previous = new Map(), previousText = new Map();
  window.auditBand = (first, end, changed) => {
    const host = document.querySelector('#space .band');
    const stats = window.scale.windowStats();
    requireTrue(stats.first === first && stats.end === end &&
      host.childElementCount === end-first, 'Window bounds or child count differ');
    const next = new Map(), nextText = new Map();
    let retainedKeys = 0, reusedKeys = 0, reusedNodes = 0, reusedTexts = 0;
    for (let i = 0; i < end-first; i++) {
      const id = first+i, node = host.children[i];
      const dirty = changed && (id % 97 === 0 || id === 999999);
      const score = (id * 37 + (id % 23) * 13) % 1000 + (dirty ? 7 : 0);
      requireTrue(node.isConnected && node.tagName === 'DIV' && node.className === 'cell' &&
        node.dataset.id === String(id) && node.textContent === id + ' · ' + score, 'Incorrect DOM at ' + id);
      const text = node.firstChild;
      requireTrue(text && text.nodeType === Node.TEXT_NODE && text === node.lastChild,
        'Cell does not contain exactly one Text node at ' + id);
      const prior = previous.get(id);
      if (prior) retainedKeys++;
      if (prior === node) reusedKeys++;
      if (previousText.has(node)) {
        reusedNodes++;
        requireTrue(previousText.get(node) === text, 'Reused cell replaced its Text at ' + id);
        reusedTexts++;
      }
      next.set(id,node);
      nextText.set(node,text);
    }
    requireTrue(retainedKeys === reusedKeys, 'Retained key lost DOM identity');
    if (identity === 'keyed') {
      for (const [id, node] of previous) if (!next.has(id)) {
        requireTrue(!node.isConnected,'Old key remains connected ' + id);
      }
    } else {
      requireTrue(reusedNodes === Math.min(previous.size, next.size), 'Slot pool remounted existing nodes');
      const kept = new Set(next.values());
      for (const node of previous.values()) if (!kept.has(node)) {
        requireTrue(!node.isConnected, 'Outgoing slot still connected');
      }
    }
    previous = next;
    previousText = nextText;
    return {first, end, retainedKeys, reusedKeys, reusedNodes, reusedTexts};
  };
}
async function marker(page, key, action) {
  await page.waitForFunction(k => window.scale.paints[k] > 0, key, {timeout:10000});
  const ms = await page.evaluate(([k,a]) => window.scale.paints[k]-window.scale.starts[a], [key,action]);
  assert.ok(ms >= -4 && Number.isFinite(ms));
  return ms;
}
async function measureJump(page) {
  const data = await page.evaluate(() => window.scale.start());
  assert.equal(data.records, count);
  const cp = await page.evaluate(() => window.scale.checkpoint());
  assert.equal(cp.count, 192);
  const mountPaintMs = await marker(page, cp.key,'mount');
  await page.evaluate(() => { window.auditBand(0,192,false); window.scale.allowUpdates(); });
  await page.locator('#mutate').click();
  const updatePaintMs = await marker(page,'mutate','mutate');
  const updated = await page.evaluate(() => {
    const model = window.scale.verifyUpdate();
    const dom = window.auditBand(0,192,true);
    return {model, dom, measurements:window.replacements.slice()};
  });
  assert.equal(updated.model.changed, 10311);
  assert.equal(updated.measurements.length,1);
  await page.locator('#jump').click();
  const seekPaintMs = await marker(page, 'jump', 'jump');
  const end = await page.evaluate(() => {
    const checked = window.scale.verifyEnd();
    const dom = window.auditBand(1000000-192,1000000,true);
    const {jump,jumpWindow,jumpRenderer,jumpRendererDone,jumpWindowDone} = window.scale.starts;
    if (!(jump <= jumpWindow && jumpWindow <= jumpRenderer && jumpRenderer <= jumpRendererDone &&
          jumpRendererDone <= jumpWindowDone)) throw Error('Destination timing order');
    return {checked, dom, measurements:window.replacements, beforeWindowMs:jumpWindow-jump,
      windowMs:jumpWindowDone-jumpWindow, outerRendererMs:jumpRendererDone-jumpRenderer};
  });
  assert.equal(end.checked.lastId, count-1);
  assert.equal(end.measurements.length,2);
  assert.equal(end.measurements[1].first,count-192);
  assert.equal(end.measurements[1].end,count);
  return {dataMs:data.dataMs,mountPaintMs,updatePaintMs,seekPaintMs,
    seekReadyReplaceMs:end.measurements[1].readyReplaceMs, seekSnapshotMs:end.measurements[1].snapshotMs,
    sparseReplaceMs:updated.measurements[0].ms, seekRendererMs:end.measurements[1].ms,
    beforeWindowMs:end.beforeWindowMs, windowMs:end.windowMs, outerRendererMs:end.outerRendererMs,
    changed:updated.model.changed,checksum:updated.model.checksum,mutateDom:updated.dom,
    destinationDom:end.dom,finalCell:end.checked};
}
async function measureScroll(positions) {
  const data = window.scale.start();
  if (data.records !== 1000000) throw Error('Wrong model size');
  const viewport = document.querySelector('#viewport');
  if (viewport.clientHeight !== 416) throw Error('Wrong viewport height');
  window.auditBand(0,192,false);
  const steps = [];
  for (const row of positions) {
    const before = window.scale.windowStats();
    const prev = window.replacements.length;
    await new Promise(resolve => {
      viewport.addEventListener('scroll',resolve,{once:true});
      viewport.scrollTop = row * 26;
    });
    await new Promise(requestAnimationFrame);
    await new Promise(requestAnimationFrame);
    const stats = window.scale.windowStats();
    const refills = window.replacements.length - prev;
    if (viewport.scrollTop !== row*26 || refills !== (row === 0 ? 0 : 1) ||
        stats.reconciles !== before.reconciles+refills) throw Error('Unexpected scroll/refill at ' + row);
    const first = refills ? Math.max(0,row-8)*8 : before.first;
    const end = refills ? (row+24)*8 : before.end;
    if (first > row*8 || end < (row+16)*8) throw Error('Viewport uncovered');
    const sample = window.replacements.at(-1);
    if (refills && (sample.first !== first || sample.end !== end)) throw Error('Unexpected renderer slice');
    const audited = window.auditBand(first,end,false);
    if (audited.retainedKeys !== Math.min(end,before.end)-Math.max(first,before.first)) throw Error('Missing overlap');
    steps.push({row, ...audited, replaceMs:refills ? sample.ms : null});
  }
  return {steps,refills:window.replacements.length,
    readyTotalMs:window.replacements[0].readyReplaceMs === undefined ? undefined : window.replacements.reduce((sum,sample) => sum+sample.readyReplaceMs,0),
    totalReplaceMs:window.replacements.reduce((sum,sample) => sum+sample.ms,0)};
}
async function main() {
  const manifest = JSON.parse(await fs.readFile(manifestPath,'utf8'));
  const names = Object.keys(manifest);
  assert.ok(names.length && names.length <= 32);
  const paths = {'/':'benchmarks/frameworks/rich/scale.html',
    '/scale.js':'benchmarks/frameworks/rich/scale.js','/sliding-window.js':'src/modules/sliding-window.js'};
  for (const name of names) {
    assert.ok(/^[a-zA-Z0-9_\-]+$/.test(name) && ['slots','keyed'].includes(manifest[name].identity));
    paths['/arm/'+name+'.js'] = manifest[name].path;
  }
  const files = new Map(), hashes = {};
  for (const [key,file] of Object.entries(paths)) {
    const bytes = await fs.readFile(file);
    files.set(key,bytes); hashes[key] = {path:file,sha256:sha(bytes),bytes:bytes.length};
  }
  files.set('/scale-saba-compiled.js',wrapper);
  const server = http.createServer((req,res) => {
    const key = req.url.split('?')[0];
    if (!files.has(key)) { res.writeHead(404); res.end(); return; }
    res.writeHead(200,{'Content-Type':key==='/'?'text/html':'text/javascript','Cache-Control':'no-store'});
    res.end(files.get(key));
  });
  await new Promise((ok,fail) => {server.once('error',fail); server.listen(0,'127.0.0.1',ok);});
  const flags = ['--renderer-process-limit=1','--js-flags=--max-old-space-size=768'];
  const report = {metadata:{date:new Date().toISOString(),cpu:os.cpus()[0].model,os:os.type()+' '+os.release(),
    rounds, count, positions, flags, viewport:[1200,900], armManifest:manifest, hashes,
    driverSha256:sha(await fs.readFile(__filename)), wrapperSha256:sha(wrapper),
    rendererClock:'Inner performance.now clock around synchronous band.replace(records). Sparse and jump are single calls. Scroll totals sum 31 calls across 32 stock-controller scroll steps. Excludes correctness checks, dispatch, and layout and paint after the call.',
    presentationClock:'Stock scale fixture Chromium Element Timing of visible status marker relative to trusted click handler entry. Final cell also hit-tested outside clock.',
    order:'Fresh Chromium per arm/round. Per round cyclic permutation of arms. Jump first via trusted sparse update and jump clicks; separate new browser context/page/model for overlapping scroll.'},visits:[]};
  try {
    for (let r=0;r<rounds;r++) for (let s=0;s<names.length;s++) {
      const name = names[(s+r)%names.length], spec = manifest[name];
      const browser = await chromium.launch({channel:'chromium',executablePath:process.env.SABA_CHROME,args:flags,timeout:20000});
      try {
        const errors = [];
        const openPage = async () => {
          const page = await browser.newPage({viewport:{width:1200,height:900}, serviceWorkers:'block'});
          page.on('pageerror', e=>errors.push(e.message));
          page.setDefaultTimeout(10000);
          await page.goto('http://127.0.0.1:'+server.address().port+'/?scenario=buffered&count='+count+'&mode=saba-compiled&arm='+name);
          await page.waitForFunction(() => Boolean(window.scale));
          await page.evaluate(installChecks,spec.identity);
          return page;
        };
        const journey = async () => {
          let page = await openPage();
          const jump = await measureJump(page);
          await page.close();
          page = await openPage();
          const scroll = await page.evaluate(measureScroll,positions);
          assert.equal(scroll.refills,31);
          let reactiveVerification;
          if (spec.verifyReactive) {
            reactiveVerification = await page.evaluate(async arm => {
              const reference = await import('/arm/'+arm+'.js');
              return await reference.verifyReactiveReference();
            }, name);
            assert.ok(reactiveVerification, 'Missing reactive verification verdict');
          }
          assert.deepEqual(errors,[]);
          return {arm:name,trial:r+1,order:s+1,chromium:browser.version(),jump,scroll,reactiveVerification};
        };
        let timeout;
        try {
          const visit = await Promise.race([journey(), new Promise((_,reject) => {
            timeout = setTimeout(() => reject(Error('Timed out '+name+' trial '+(r+1))),55000);
          })]);
          report.visits.push(visit);
          await fs.writeFile(output+'.tmp',JSON.stringify(report,null,2)+'\n');
          await fs.rename(output+'.tmp',output);
          console.log(r+1,name,'jump',visit.jump.seekRendererMs.toFixed(2),
            'scroll',visit.scroll.totalReplaceMs.toFixed(2),'paint',visit.jump.seekPaintMs.toFixed(2));
        } finally { clearTimeout(timeout); }
      } finally { await browser.close(); }
    }
  } finally { await new Promise(resolve=>server.close(resolve)); }
}
main().catch(error=>{console.error(error);process.exitCode=1;});
